// Read-only appearance projection shared by rail, palette and Inspector.
export function paintState(objects,target,defaults={}){const eligible=objects.filter(o=>target==='stroke'?o.type!=='image':['path','text'].includes(o.type));if(!eligible.length)return {kind:defaults[target]==='none'?'none':'solid',value:defaults[target]||'#ffffff',label:'Color activo'};const states=eligible.map(o=>target==='fill'&&o.gradient?{kind:'gradient',value:o.gradient}:{kind:!o[target]||o[target]==='none'?'none':'solid',value:o[target]||'none'});const first=states[0];if(states.some(s=>JSON.stringify(s)!==JSON.stringify(first)))return {kind:'mixed',value:null,label:'Valores mixtos'};return {...first,label:first.kind==='gradient'?'Degradado':first.kind==='none'?'Sin color':first.value};}
export function paintCss(state){if(state.kind==='gradient')return `linear-gradient(90deg,${state.value.stops.map(s=>`${s.color} ${s.offset*100}%`).join(',')})`;if(state.kind==='mixed')return 'repeating-linear-gradient(135deg,#83928c 0 4px,#e9eeeb 4px 8px)';if(state.kind==='none')return 'linear-gradient(135deg,transparent 45%,#c74848 46% 54%,transparent 55%)';return state.value;}
